INSERT INTO content_items (title, content, "order", chapter_id) VALUES
('The Cat and the Dog', '{"type": "article", "text": "A cat and a dog lived in a small house. They were good friends. Every day they played together in the garden.", "imageUrl": "https://example.com/cat-dog.jpg"}', 1, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Family', '{"type": "article", "text": "I have a big family. My mother is a teacher. My father works in a bank. I have one sister and one brother.", "imageUrl": "https://example.com/family.jpg"}', 2, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Colors in Nature', '{"type": "article", "text": "Look at the sky. It is blue. The grass is green. The sun is yellow. Flowers can be red, pink, or white.", "imageUrl": "https://example.com/nature.jpg"}', 3, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('A Day at School', '{"type": "article", "text": "I go to school every morning. I carry my bag with books and a pencil. My teacher is very nice. We learn many things.", "imageUrl": "https://example.com/school.jpg"}', 4, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Weather Today', '{"type": "article", "text": "Today is sunny. The birds are singing. Children are playing outside. It is a beautiful day for a walk.", "imageUrl": "https://example.com/sunny-day.jpg"}', 5, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Animals at the Zoo', '{"type": "article", "text": "At the zoo, we can see many animals. There are lions, elephants, and monkeys. The elephants are very big.", "imageUrl": "https://example.com/zoo.jpg"}', 6, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Favorite Food', '{"type": "article", "text": "I like to eat apples and bananas. Pizza is my favorite dinner. I drink milk every day. Vegetables are good for me.", "imageUrl": "https://example.com/food.jpg"}', 7, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Playing in the Park', '{"type": "article", "text": "The park has many trees and flowers. Children run and play games. There is a big slide and swings to play on.", "imageUrl": "https://example.com/park.jpg"}', 8, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Bedroom', '{"type": "article", "text": "My bedroom is small but nice. I have a bed, a desk, and a chair. My toys are in a big box near the window.", "imageUrl": "https://example.com/bedroom.jpg"}', 9, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Little Bird', '{"type": "article", "text": "A little bird sits on a tree. It sings beautiful songs every morning. The bird has yellow feathers and a small beak.", "imageUrl": "https://example.com/bird.jpg"}', 10, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Shopping with Mom', '{"type": "article", "text": "I go shopping with my mom. We buy bread, milk, and fruits. The store is big and has many things to choose from.", "imageUrl": "https://example.com/shopping.jpg"}', 11, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Pet Fish', '{"type": "article", "text": "I have a pet fish in a bowl. The fish is orange and swims all day. I feed my fish every morning before school.", "imageUrl": "https://example.com/fish.jpg"}', 12, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Magic Garden', '{"type": "article", "text": "In the garden, there are many flowers. Bees fly from flower to flower. Butterflies dance in the warm sunshine.", "imageUrl": "https://example.com/garden.jpg"}', 13, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Birthday Party', '{"type": "article", "text": "Today is my birthday! I have a big cake with candles. My friends come to my party. We play games and eat cake.", "imageUrl": "https://example.com/birthday.jpg"}', 14, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Busy Street', '{"type": "article", "text": "The street is very busy. Cars and buses move slowly. People walk on the sidewalk. There are many shops and buildings.", "imageUrl": "https://example.com/street.jpg"}', 15, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Reading a Book', '{"type": "article", "text": "I love to read books. My favorite book has pictures of animals. Reading helps me learn new words and ideas.", "imageUrl": "https://example.com/reading.jpg"}', 16, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Beach Day', '{"type": "article", "text": "We go to the beach on weekends. The sand is warm and soft. The waves make a nice sound. I like to build sandcastles.", "imageUrl": "https://example.com/beach.jpg"}', 17, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('Cooking with Dad', '{"type": "article", "text": "My dad teaches me how to cook. We make soup together. Cooking is fun when we do it as a team.", "imageUrl": "https://example.com/cooking.jpg"}', 18, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('The Night Sky', '{"type": "article", "text": "At night, the sky is dark. I can see the moon and many stars. The stars look like tiny lights in the sky.", "imageUrl": "https://example.com/night-sky.jpg"}', 19, 'd596f9fe-028f-48f0-8a1f-174650acd861'),
('My Best Friend', '{"type": "article", "text": "My best friend lives next door. We play together every day. She has long hair and likes to draw pictures.", "imageUrl": "https://example.com/friends.jpg"}', 20, 'd596f9fe-028f-48f0-8a1f-174650acd861');